type Category = { id:string; name:string; color:string };
type Task = RecurringTask & { id:string; title:string; description:string; categoryId:string; engagement:'deep'|'shallow'; length:'short'|'long'; priority:number; createdAt:string };
type Session = { id:string; categoryId:string; taskId:string; taskTitle:string; mode:'stopwatch'|'timer'; startedAt:string; endedAt:string; durationSeconds:number; note:string };
type Settings = { showUpcoming:boolean; upcomingLimit:number; showRecent:boolean; recentLimit:number; googleClientId:string; googleSheetId:string; googleAutoSync:boolean };
type WeekTaskTime = { key:string; title:string; seconds:number };
type WeekSegment = { categoryId:string; name:string; color:string; seconds:number; tasks:WeekTaskTime[] };
const weekDates=()=>Array.from({length:7},(_,index)=>{const date=new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()-(6-index));return date});
const weekSegments=(sessions:Session[],day:string,categories:Category[]):WeekSegment[]=>{const grouped=new Map<string,Session[]>();for(const session of sessions){if(localDateKey(new Date(session.startedAt))!==day)continue;const key=session.categoryId||'';grouped.set(key,[...(grouped.get(key)??[]),session])}const ids=[...categories.map(category=>category.id).filter(id=>grouped.has(id)),...(grouped.has('')?['']:[]),...[...grouped.keys()].filter(id=>id&&!categories.some(category=>category.id===id))];return ids.map(id=>{const list=grouped.get(id)??[];const category=categories.find(item=>item.id===id);const tasks=new Map<string,WeekTaskTime>();for(const session of list){const key=session.taskId||`title:${session.taskTitle}`;const title=session.taskTitle.trim()||'No task linked';const current=tasks.get(key)??{key,title,seconds:0};current.seconds+=session.durationSeconds;tasks.set(key,current)}return {categoryId:id||'none',name:category?.name||'No category',color:category?.color||'#9aa69f',seconds:list.reduce((sum,session)=>sum+session.durationSeconds,0),tasks:[...tasks.values()].sort((a,b)=>b.seconds-a.seconds||a.title.localeCompare(b.title))}}).filter(segment=>segment.seconds>0)};
type Store = { categories:Category[]; tasks:Task[]; sessions:Session[]; settings:Settings };
